"""Shared ROLL/pass, real requests, restart and transaction fault injection."""
import copy,json,os,time
from pathlib import Path
from uuid import uuid4
from balance_fixture import BalanceFixture,ROOT
from run_loot_instances import LootPlayer
from run_online_pve import api
def main():
    checks=[];fixtures=[];lifecycle={};starts=[]
    def check(ok,label):
        assert ok,label
        checks.append(label)
    with BalanceFixture() as f:
        identities=[f.create('roll_'+c,1) for c in 'abc'];a,b,c=identities;players=[]
        initial=copy.deepcopy(json.loads(Path(os.environ.get('SSJX_PROGRESSION_VECTORS','/tmp/opencode/progression-vectors.json')).read_text())['crafts'][1]['before']);prototype=initial['items'][0];initial['items']=[];initial['kills']=7
        for _ in range(58):
            item=copy.deepcopy(prototype);item.update(id=str(uuid4()),quality='white',level=1,affixes=[]);initial['items'].append(item)
        for who in identities:
            f.db.query(f"UPDATE characters SET level=60,hp=1000,mp=480,gold=10000,quest_stage=1,cell_x=22,cell_y=9,allocated_attributes=ARRAY[60,0,180,60,0],loot_state=jsonb_set(loot_state,'{{kills}}','7') WHERE id='{who[1]}'")
        f.db.query(f"UPDATE characters SET loot_state='{json.dumps(initial)}'::jsonb WHERE id='{a[1]}'; UPDATE inventory_items SET quantity=99 WHERE character_id='{a[1]}' AND definition_id='potion'")
        def connect_all():
            players.clear()
            for who in identities:
                p=LootPlayer(f.base,*who);players.append(p);f.clients.append(p)
        connect_all()
        def send(who,action,code='OK',request=None,**fields):
            for p in players:
                if not getattr(p,'fixture_closed',False) and time.monotonic()-getattr(p,'keepalive',0)>2:p.ws.send({'type':'ping'});p.keepalive=time.monotonic()
            request=request or dict(character_id=who[1],action=action,**fields)
            if action!='snapshot' and 'operation_id' not in request:request['operation_id']=str(uuid4())
            status,value=api(f.base,'/api/v1/teams',request,who[0]['access_token']);assert status==200 and value['code']==code,(status,value,code)
            return value,request
        def battle():return send(a,'snapshot')[0]['state']['team']['battle']
        def choose(who,action,index=0,request=None,code='OK'):
            b=battle();return send(who,action,code,request=request,target=b['loot_pool']['drops'][index]['item']['id'],battle_id=b['id'],expected_revision=b['loot_pool']['revision'])
        def finish(target='spirit'):
            for who in identities[1:]:send(who,'ready',ready=True)
            result,_=send(a,'challenge',target=target,encounter_version=2);b=result['state']['team']['battle']
            starts.append(send(c,'snapshot')[0])
            for _ in range(20):
                if b['outcome']!='active':break
                if b['selection_starts_ms']>int(time.time()*1000):f.db.query("UPDATE team_battles SET state=jsonb_set(jsonb_set(state,'{selection_starts_ms}',to_jsonb((extract(epoch FROM statement_timestamp())*1000)::bigint-1)),'{deadline_ms}',to_jsonb((extract(epoch FROM statement_timestamp())*1000)::bigint+29999)) WHERE active")
                target_slot=next(e['slot'] for e in b['enemies'] if e['hp']>0);revision=b['revision']
                for who in identities:
                    result,_=send(who,'attack',target=target_slot,battle_id=b['id'],expected_revision=revision);b=result['state']['team']['battle']
            check(b['outcome']=='victory','Actual three-player shared encounter reaches victory')
            return result
        send(a,'invite',target=b[1]);offer=send(b,'snapshot')[0]['state']['incoming'][0]['id'];send(b,'accept',target=offer)
        send(a,'invite',target=c[1]);offer=send(c,'snapshot')[0]['state']['incoming'][0]['id'];send(c,'accept',target=offer)
        result=finish();fixtures.append(result);pool=battle()['loot_pool'];item_id=pool['drops'][0]['item']['id']
        lifecycle['first_active']=starts[0];lifecycle['pending']=send(c,'snapshot')[0]
        check(len(pool['drops'])==1,'A normal pity encounter creates one shared item, not one copy per player')
        rejected,_=send(a,'challenge','TEAM_LOOT_PENDING',target='spirit',encounter_version=2)
        check(rejected['state']['team']['battle']['id']==result['state']['team']['battle']['id'],'Challenging again while loot is pending keeps the original ended battle; it never creates a new encounter')
        result,first=choose(a,'loot_roll');score=result['state']['team']['battle']['loot_pool']['drops'][0]['choices'][a[1]];check(1<=score<=100,'ROLL score is generated by the server within 1..100')
        lifecycle['partial']=send(c,'snapshot')[0]
        fixtures.append(result);send(a,'disband','TEAM_LOOT_PENDING');choose(a,'loot_roll',code='TEAM_LOOT_DECIDED')
        f.restart();connect_all();check(battle()['loot_pool']['drops'][0]['choices'][a[1]]==score,'Restart preserves the committed roll and original deadline')
        result,_=choose(a,'loot_roll',request=first);check(result['replayed'] and result['state']['team']['battle']['loot_pool']['drops'][0]['choices'][a[1]]==score,'Retry cannot reroll a committed score')
        players[0].close();players[0].fixture_closed=True;time.sleep(.2)
        choose(b,'loot_pass')
        before=f.db.query('SELECT id,loot_state,state_revision FROM characters ORDER BY id')
        f.db.query("CREATE FUNCTION reject_roll_award() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.loot_state IS DISTINCT FROM OLD.loot_state THEN RAISE EXCEPTION 'owned roll rollback'; END IF; RETURN NEW; END$$; CREATE TRIGGER reject_roll_award BEFORE UPDATE ON characters FOR EACH ROW EXECUTE FUNCTION reject_roll_award();")
        current=battle();request=dict(character_id=c[1],action='loot_pass',operation_id=str(uuid4()),target=item_id,battle_id=current['id'],expected_revision=current['loot_pool']['revision'])
        status,_=api(f.base,'/api/v1/teams',request,c[0]['access_token']);check(status==503 and f.db.query('SELECT id,loot_state,state_revision FROM characters ORDER BY id')==before,'Inventory, final choice and receipt roll back together when the award cannot commit')
        check(c[1] not in battle()['loot_pool']['drops'][0]['choices'],'Failed delivery cannot consume the last participant decision')
        f.db.query('DROP TRIGGER reject_roll_award ON characters; DROP FUNCTION reject_roll_award();')
        result,_=choose(c,'loot_pass',request=request);fixtures.append(result)
        lifecycle['resolved']=send(c,'snapshot')[0]
        loot=json.loads(f.db.query(f"SELECT loot_state FROM characters WHERE id='{a[1]}'"));check(loot['pending'][0]['id']==item_id and battle()['loot_pool']['drops'][0]['winner']==a[1],'An offline roller still wins the original UUID into pending storage when their backpack is full')
        before=f.db.query('SELECT id,loot_state,state_revision FROM characters ORDER BY id');choose(c,'loot_pass',request=request)
        check(f.db.query('SELECT id,loot_state,state_revision FROM characters ORDER BY id')==before,'Award replay cannot duplicate an item or consume capacity twice')
        # Move the owned fixture to an actual original boss for two shared drops.
        boss=next(r for r in json.loads((ROOT/'shared/data/ruins-population-v1.json').read_text()) if r['id']=='boss')
        for p in players:p.close()
        f.restart() # Drain old room ownership before moving only the disposable characters.
        for who in identities:f.db.query(f"UPDATE characters SET map_id='ancient_ruins',cell_x={boss['cell'][0]},cell_y={boss['cell'][1]-1},monster_respawns='{{}}'::jsonb,hunt_pressure='{{}}'::jsonb WHERE id='{who[1]}'")
        time.sleep(.2);connect_all();result=finish('boss');check(len(battle()['loot_pool']['drops'])==2,'Boss victory creates two separately decidable common drops')
        lifecycle['next_active']=starts[1];lifecycle['next_pending']=send(c,'snapshot')[0]
        check(lifecycle['next_active']['state']['team']['battle']['id']!=lifecycle['resolved']['state']['team']['battle']['id'] and 'loot_pool' not in lifecycle['next_active']['state']['team']['battle'],'The next authoritative battle has a new ID and contains no previous loot pool')
        current=battle();pool=current['loot_pool'];shared_id=pool['drops'][0]['item']['id']
        from concurrent.futures import ThreadPoolExecutor
        def roll(who):
            request=dict(character_id=who[1],action='loot_roll',operation_id=str(uuid4()),target=shared_id,battle_id=current['id'],expected_revision=pool['revision'])
            return api(f.base,'/api/v1/teams',request,who[0]['access_token'])
        with ThreadPoolExecutor(max_workers=2) as executor:responses=list(executor.map(roll,[a,b]))
        check(all(status==200 and value['ok'] for status,value in responses),'Concurrent players can roll from the same pool revision without stale-choice races')
        result,_=choose(c,'loot_pass',0);fixtures.append(result);d=battle()['loot_pool']['drops'][0]
        scores=d['tie_scores'] or {id:score for id,score in d['choices'].items() if score is not None}
        check(d['delivered'] and scores[d['winner']]==max(scores.values()),'Among multiple real server-generated rolls the highest point wins exactly once')
        for who in identities:result,_=choose(who,'loot_pass',1)
        fixtures.append(result);d=battle()['loot_pool']['drops'][1];check(d['winner'] is None and d['delivered'],'Players may roll on one item and all pass on the other; passed loot creates no private copies')
        for who in identities:f.db.query(f"UPDATE characters SET monster_respawns='{{}}'::jsonb,hunt_pressure='{{}}'::jsonb WHERE id='{who[1]}'")
        result=finish('boss');choose(a,'loot_roll',0);item_id=battle()['loot_pool']['drops'][0]['item']['id']
        lifecycle['timeout_pending']=send(c,'snapshot')[0]
        f.db.query("UPDATE team_battles SET state=jsonb_set(state,'{loot_pool,deadline_ms}',to_jsonb((extract(epoch FROM statement_timestamp())*1000)::bigint-1)) WHERE state->'loot_pool' IS NOT NULL")
        result,_=send(a,'snapshot');fixtures.append(result);pool=result['state']['team']['battle']['loot_pool']
        lifecycle['timeout_resolved']=send(c,'snapshot')[0]
        check(pool['drops'][0]['winner']==a[1] and pool['drops'][1]['winner'] is None and all(d['delivered'] for d in pool['drops']),'Timeout automatically passes undecided members, honors existing rolls and discards the unrolled second item')
        check(any(i['id']==item_id for i in json.loads(f.db.query(f"SELECT loot_state FROM characters WHERE id='{a[1]}'"))['pending']),'Timed-out distribution still delivers the original immutable item safely')
        check(api(f.base,'/api/v1/teams',dict(character_id=a[1],action='loot_roll',operation_id=str(uuid4()),roll=100),a[0]['access_token'])[0]==400,'Clients cannot submit a forged roll score')
        for who in identities:f.db.query(f"UPDATE characters SET monster_respawns='{{}}'::jsonb,hunt_pressure='{{}}'::jsonb WHERE id='{who[1]}'")
        send(a,'challenge',target='boss',encounter_version=2);lifecycle['after_timeout']=send(c,'snapshot')[0]
        check(lifecycle['after_timeout']['state']['team']['battle']['outcome']=='active','A completed timeout permits the next encounter without waiting for clients to close their result overlays')
        before=f.db.query('SELECT id,loot_state FROM characters ORDER BY id')
        old=lifecycle['timeout_resolved']['state']['team']['battle']
        send(c,'loot_pass','TEAM_LOOT_NOT_FOUND',target=old['loot_pool']['drops'][0]['item']['id'],battle_id=old['id'],expected_revision=old['loot_pool']['revision'])
        check(f.db.query('SELECT id,loot_state FROM characters ORDER BY id')==before,'A stale loot-panel request during the new battle cannot redistribute old equipment')
    output=ROOT/'work/team-loot';output.mkdir(parents=True,exist_ok=True);(output/'server-fixtures.json').write_text(json.dumps(fixtures,ensure_ascii=False))
    (output/'lifecycle-fixtures.json').write_text(json.dumps(lifecycle,ensure_ascii=False))
    print(f'TEAM LOOT SERVER: {len(checks)} checks, 0 failures')
if __name__=='__main__':main()
